import { useState } from "react";
import TrialForm from "../TrialForm/TrialForm";
import NavBar from "../NavBar/NavBar";
import style from "./LandingPage.module.css";

export default function LandingPage() {
  const [showTrialForm, setShowTrialForm] = useState(false);

  return (
    <div className={style.landingPage}>
      <div className={style.landingPage__hero}>
        <div className={style.landingPage__text}>
          <h1 className={style.landingPage__title}>Train with Purpose</h1>
          <p className={style.landingPage__subtitle}>
            Discover your journey in Brazilian Jiu Jitsu. Join classes for all ages and levels.
          </p>
        </div>
      </div>
    </div>
  );
}
